        for (let yy = yTop; yy <= H; yy += step) { const amp = 46 * (0.35 + 0.65 * (yy / H)); const sw = Math.sin(yy * 0.024 + t * 2 + ph) * amp; const w = 9 * (yy / H) + 4; const xx = colX + sw; ctx.lineTo(xx + w, yy); }
