      let dx = next.x - prev.x, dy = next.y - prev.y; const L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
      const nx = -dy, ny = dx, w = maxW * Math.pow(i / (rn - 1), 0.8);
