      x: _vikX, y: _vikY, vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd,
      rot: Math.random() * 6.28, vr: (Math.random() - 0.5) * 26,
      suit: _VIK_SUITS[(Math.random() * 4) | 0], rank: _VIK_RANKS[(Math.random() * _VIK_RANKS.length) | 0],
