  ctx.strokeStyle = _JK_GOLD; ctx.lineWidth = Math.max(3, S * 0.07); ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(w / 2 + BK[0] * 0.5 - S * 0.1, rcy); ctx.lineTo(rcx + S * 0.32, rcy); ctx.stroke();
  ctx.save();
