  ctx.translate(0, -1);
  wingShape(1, wing * 16);
  const wg = ctx.createLinearGradient(2, 0, 30, -20);
  wg.addColorStop(0, `rgba(255,196,80,${(0.95).toFixed(2)})`);
  wg.addColorStop(1, `rgba(255,80,24,${(0.85).toFixed(2)})`);
