  for (let i = 0; i < N; i++) { const cu = P(i), nx = P(i + 1); ctx.quadraticCurveTo(cu[0], cu[1], (cu[0] + nx[0]) / 2, (cu[1] + nx[1]) / 2); }
  ctx.closePath();
