    for (let gx = -1; gx <= 1; gx++) for (let gy = -1; gy <= 1; gy++) { ctx.beginPath(); ctx.arc(fx + gx * 4.4, cy + gy * 4.4, 1.4, 0, PI2); ctx.fill(); }
