    const TS = 86;
    for (let yy = 0, ry = 0; yy < H + TS; yy += TS, ry++)
      for (let xx = 0, rx = 0; xx < W + TS; xx += TS, rx++)
        _leTileMotif(s, xx, yy, TS, (rx + ry) % 2);
