    ctx.strokeStyle = 'rgba(220,220,220,0.22)'; ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 0; i <= n; i++) { const fx = i * span, fy = baseY + Math.sin(i * 0.6 + t * 0.8) * 4 * down; i ? ctx.lineTo(fx, fy) : ctx.moveTo(fx, fy); }
    ctx.stroke();
