    const vig = ctx.createRadialGradient(cx, cy, Math.min(W, H) * 0.3, W * 0.5, H * 0.5, Math.max(W, H) * 0.74);
    vig.addColorStop(0, 'rgba(0,0,0,0)'); vig.addColorStop(1, 'rgba(2,3,6,0.72)');
