  ctx.beginPath(); ctx.ellipse(s * 0.2, -s * 0.24, s * 0.17, s * 0.12, 0.3, 0, 7); ctx.fill(); ctx.stroke();   // head
  ctx.beginPath(); ctx.ellipse(s * 0.35, -s * 0.17, s * 0.09, s * 0.07, 0.2, 0, 7); ctx.fill(); ctx.stroke();   // snout
