    for (let px = 12; px < W; px += 26) { s.lineWidth = 1.2; s.beginPath(); s.moveTo(px - 3, fenceY - 3); s.lineTo(px + 3, fenceY + 3); s.moveTo(px + 3, fenceY - 3); s.lineTo(px - 3, fenceY + 3); s.stroke(); }
