  ctx.strokeStyle = 'rgba(0,0,0,0.4)'; for (let i = 0; i < 6; i++) { ctx.beginPath(); ctx.moveTo(16 + i * 3, -5.5); ctx.lineTo(16 + i * 3, 5.5); ctx.stroke(); }
