  ctx.fillStyle = '#fffdf6'; ctx.strokeStyle = _RK_INK; ctx.lineWidth = 3; ctx.lineJoin = 'round';
  _jhRound(ctx, -bw / 2, -bh, bw, bh, r); ctx.fill();
