  _jhRound(ctx, -bw / 2, -bh, bw, bh, r); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-bw * 0.18, -1); ctx.lineTo(-bw * 0.34, 16); ctx.lineTo(-bw * 0.04, -1); ctx.stroke();
