  gg.addColorStop(0, `rgba(255,231,120,${(0.55 * bright).toFixed(3)})`); gg.addColorStop(1, 'rgba(255,231,120,0)');
  ctx.fillStyle = gg; ctx.beginPath(); ctx.arc(0, 0, r * 2.6, 0, PI2); ctx.fill();
