      const bx = _syHash(i * 1.7) * W, by = _syHash(i * 2.9 + 1) * H, br = 18 + _syHash(i * 3.3) * 70;
      const cols = ['255,180,225', '160,215,255', '170,235,200', '255,255,255'];
      const c = cols[i % 4];
