    ribbon(H * 0.82, H * 0.18, 'rgba(150,230,185,0.4)', 'rgba(110,210,150,0.05)');    // green accent
    ribbon(H * 0.6, H * 0.13, 'rgba(255,180,222,0.5)', 'rgba(255,150,205,0.06)');     // pink (front)
