  if (open01 <= 0.02) return;
  const PI2 = Math.PI * 2;
  const s1 = _hrHash((seed || 0) * 13 + 2), s2 = _hrHash((seed || 0) * 29 + 5), s3 = _hrHash((seed || 0) * 7 + 11);
  const w = sz, h = sz * 0.6 * open01;
