    ctx.quadraticCurveTo(w * 0.42, -h * (1.7 + s1 * 0.4), w, 0);
    ctx.quadraticCurveTo(w * 0.5, h * (1.5 + s2 * 0.6), -w * 0.1, h * (1.7 + s1 * 0.45));
