  ctx.strokeStyle = 'rgba(105,24,66,0.42)';
  ctx.lineWidth = 0.8;
  ctx.beginPath(); ctx.moveTo(-w, 0); ctx.quadraticCurveTo(-w * 0.6, -h * 0.4, -w * 0.35 + ix * 0.3, iy * 0.5 - h * 0.2); ctx.stroke();
