      const depth = 0.4 + _clHash(i * 53 + 9) * 0.6;
      const py3 = ((t * (8 + sd * 13) * depth + sd * (H + 80)) % (H + 80)) - 40;
      const px3 = sd2 * W + Math.sin(t * 0.4 + i * 2.3) * 40 * depth;
      const rot = t * (0.45 + sd * 0.55) * (i % 2 ? -1 : 1) + Math.sin(t * 1.2 + i) * 0.4;
