      ctx.quadraticCurveTo(-ps * 0.95, -ps * 0.15, 0, -ps);
      ctx.closePath();
      ctx.fillStyle = `rgba(255,205,90,${((0.18 + sd * 0.22) * depth + 0.07).toFixed(3)})`;
