    const gg = ctx.createRadialGradient(_cdMX, _cdMY, 0, _cdMX, _cdMY, gr);
    gg.addColorStop(0, `rgba(255,22,26,${(0.10 + swingK * 0.12 + _cdChargeAmt * 0.16).toFixed(3)})`);
    gg.addColorStop(1, 'rgba(255,22,26,0)');
