  ctx.shadowBlur = 8 + Math.sin(t * 3.1) * 2.5 + swingK * 8 + _cdChargeAmt * 10;
  ctx.drawImage(kn, -4, -kn.height + 4);        // tip (bottom-left of sprite) at the pointer
  ctx.restore();

