  const breathe = 0.5 + 0.5 * Math.sin(t * 1.05);

  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#070310'; ctx.fillRect(0, 0, W, H);

  // ── chunky pixel rainbow flowing out of a glowing core ──
  const PX = 16;
