  const PI2 = Math.PI * 2;
  const breathe = 0.5 + 0.5 * Math.sin(t * 0.5);     // very slow, melancholic

  ctx.clearRect(0, 0, W, H);

  // cold dusk backdrop + a pale light bleeding from above
