    const dy = (((sd * 5.3 - t * 0.01 * (0.5 + (sd % 1))) % 1) + 1) % 1 * H;
    ctx.fillStyle = `rgba(220,214,190,${(0.04 + (sd % 0.12)).toFixed(3)})`;
