  _drawTobuPattern._lt        = undefined;
  _drawLalaPattern._lt        = undefined;
  _drawXyliarPattern._lt      = undefined;
  _drawXyliarOverlay._lt      = undefined;
  _drawRadyPattern._lt        = undefined;
  _drawRadyOverlay._lt        = undefined;
  _drawLeonHumanPattern._lt   = undefined;
  _drawLeonHumanOverlay._lt   = undefined;
  _drawSevachPattern._lt      = undefined;
  _drawSevachOverlay._lt      = undefined;
  _drawAdamHumanPattern._lt   = undefined;
  _drawAdamHumanOverlay._lt   = undefined;
  _drawLibraPattern._lt       = undefined;
  _drawLibraOverlay._lt       = undefined;
  _drawPlumkyPattern._lt      = undefined;
  _drawPlumkyOverlay._lt      = undefined;
  _drawMbPattern._lt          = undefined;
  _drawMbOverlay._lt          = undefined;
  _drawEmporiumPattern._lt    = undefined;
  _drawEmporiumOverlay._lt    = undefined;
  _drawAlsacePattern._lt      = undefined;
  _drawAlsaceOverlay._lt      = undefined;
  _drawJeckelyPattern._lt     = undefined;
  _drawJeckelyOverlay._lt     = undefined;
